import{_ as e,o as i,c as t,aw as o}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"SOAP","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/api/soap.md","filePath":"wiki/dev-commit/network/network/api/soap.md"}'),l={name:"wiki/dev-commit/network/network/api/soap.md"};function r(n,a,s,c,d,P){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="soap" tabindex="-1">SOAP <a class="header-anchor" href="#soap" aria-label="Permalink to &quot;SOAP&quot;">​</a></h1><ul><li><strong>SOAP</strong> (Simple Object Access Protocol — простой протокол доступа к объектам) - протокол обмена структурированными сообщениями в распределённой вычислительной среде</li><li>Сейчас протокол используется для обмена произвольными сообщениями в формате XML</li><li>SOAP может использоваться с любым протоколом прикладного уровня: SMTP / FTP / HTTP / HTTPS и др. Однако его взаимодействие с каждым из этих протоколов имеет свои особенности, которые должны быть определены отдельно. Чаще всего SOAP используется поверх HTTP</li><li>SOAP является одним из стандартов, на которых базируются технологии веб-служб</li></ul><h2 id="структура-протокола-сообщения" tabindex="-1">Структура протокола (сообщения) <a class="header-anchor" href="#структура-протокола-сообщения" aria-label="Permalink to &quot;Структура протокола (сообщения)&quot;">​</a></h2><ul><li>Envelope - корневой элемент, который определяет сообщение и пространство имен, использованное в документе</li><li>Header - содержит атрибуты сообщения, например: информация о безопасности или о сетевой маршрутизации</li><li>Body - содержит сообщение, которым обмениваются приложения</li><li>Fault - необязательный элемент, который предоставляет информацию об ошибках, которые произошли при обработке сообщений</li></ul><h2 id="недостатки" tabindex="-1">Недостатки <a class="header-anchor" href="#недостатки" aria-label="Permalink to &quot;Недостатки&quot;">​</a></h2><ul><li>Использование SOAP для передачи сообщений увеличивает их объём и снижает скорость обработки. В системах, где скорость важна, чаще используется пересылка XML-документов через HTTP напрямую, где параметры запроса передаются как обычные HTTP-параметры</li></ul>',6)])])}const m=e(l,[["render",r]]);export{_ as __pageData,m as default};
